212	    #[test]
213	    fn read_overlong_nul_replaced_with_fffd() {
214	        // 0xC0 0x80 is overlong NUL → c=0 → <0x80 → 0xFFFD
215	        assert_eq!(utf8_read(&[0xC0, 0x80]), (0xFFFD, 2));
216	    }
217	
218	    #[test]
219	    fn read_continuation_byte_as_leader() {
220	        // 0x80..=0xBF as first byte: returned as literal single byte.
221	        assert_eq!(utf8_read(&[0x80, 0x80]), (0x80, 1));
222	        assert_eq!(utf8_read(&[0xBF]), (0xBF, 1));
223	    }
224	
225	    #[test]
226	    fn read_empty() {
227	        assert_eq!(utf8_read(b""), (0, 0));
228	    }
229	
230	    #[test]
231	    fn write_ascii() {
232	        let mut buf = [0u8; 4];
233	        let n = utf8_write(&mut buf, 0x41, 4);
234	        assert_eq!(n, 1);
235	        assert_eq!(buf[0], 0x41);
236	    }
