238	    #[test]
239	    fn write_two_byte() {
240	        let mut buf = [0u8; 4];
241	        let n = utf8_write(&mut buf, 0xA0, 4);
242	        assert_eq!(n, 2);
243	        assert_eq!(buf, [0xC2, 0xA0, 0, 0]);
244	    }
245	
246	    #[test]
247	    fn write_three_byte() {
248	        let mut buf = [0u8; 4];
249	        let n = utf8_write(&mut buf, 0x4E2D, 4);
250	        assert_eq!(n, 3);
251	        assert_eq!(buf, [0xE4, 0xB8, 0xAD, 0]);
252	    }
253	
254	    #[test]
255	    fn write_four_byte() {
256	        let mut buf = [0u8; 4];
257	        let n = utf8_write(&mut buf, 0x1F600, 4);
258	        assert_eq!(n, 4);
259	        assert_eq!(buf, [0xF0, 0x9F, 0x98, 0x80]);
260	    }
